"Anyone remember why the sky is a portal?":"Pamätá si niekto, prečo je obloha portál?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Vraj keď skočíš do šachty, vyletíš u nepriateľa. Skúšať to nebudem.",
"The Swarm painted their visors red again. Show-offs.":"Roj si zasa natrel priezory načerveno. Fičúri.",
"Ore, ore… when do we get some oil?":"Ruda, ruda… a kedy dostaneme olej?",
