"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Vitaj na meteore! Si bojový robot Konzorcia. Rozhliadni sa myšou a choď: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: ťukni na Shift — skok, drž Shift — let. Energia sa obnovuje na zemi.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Strieľaj — ľavé tlačidlo. Zameriavač — pravé tlačidlo: presnejšie a s priblížením. Urob niekoľko výstrelov.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Prebíjanie — R. Náboje bijú najsilnejšie na strednú vzdialenosť, 20–50 metrov.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Proti tankom a budovám. Vypusti raketu.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Hore je úloha od stratéga. Bež po zelených šípkach: na trase máš šprint. Ovládni bod — stoj pri majáku.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tvoje družstvo ťa kryje: vľavo sú ich portréty a zdravie. Ak zaostávajú, vojaci ťa požiadajú počkať.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — rýchle prepnutie jednotky bez opustenia boja: skok k družstvu alebo tanku najbližšie k boju. Vyskúšaj.",
"Next to a tank or turret press E to take control. Or just carry on.":"Pri tanku alebo veži stlač E a prevezmi ovládanie. Alebo len pokračuj ďalej.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Teraz stratégia. Ťukni na „◩ Stratégia\" vpravo hore — pohľad zhora na bojisko.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Teraz stratégia. Stlač {0} (alebo „◩ Stratégia\" vľavo hore) — pohľad zhora na bojisko.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"V stratégii ti pomáha Sprievodca: okno hore hovorí, čo urobiť, rámik ukazuje tlačidlo, kruh označuje miesto na mape. Splň tri jeho rady.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Vyber družstvo a ťukni na zelené tlačidlo „▶ Ovládnuť\" — späť do boja za tohto vojaka. Kým strieľaš, AI stratég velí armáde sám.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Vyber družstvo a stlač {0} alebo zelené „▶ Ovládnuť\" — späť do boja za tohto vojaka (bez výberu — za svojho). Kým strieľaš, AI stratég velí armáde sám.",
