"The heavy MG is a reward the strategist hands out for completed orders.":"Ťažký guľomet dáva stratég ako odmenu za splnený rozkaz.",
"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} sa odomkne na hodnosti „{1}\". Skúsenosti dávajú zabitia, ovládnutie bodov a rozkazy stratéga (×2–×3).",
"Left thumb — move, right thumb — look. Red button — fire.":"Ľavý palec — pohyb, pravý — pohľad. Červené tlačidlo — paľba.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — jetpack: ťuknutím skočíš, podržaním letíš. ◎ — zameriavač.",
"In the air, ⤓ is the jet brake.":"Vo vzduchu ⤓ je brzda jetpacku.",
"Move and shoot: mouse to look, LMB to fire.":"Hýb sa a strieľaj: myš — pohľad, ľavé tlačidlo — paľba.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Hore je rozkaz AI stratéga. Plň ho: skúsenosti ×2 a ×3, za splnenie bývajú odmeny. Zelený marker a šípky ťa vedú k cieľu.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: ťuknutím skočíš, podržaním letíš. Pravé tlačidlo — zameriavač.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"Vo vzduchu je C brzda jetpacku. Zabrzdi, otoč sa pohľadom a daj ťah znova.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"Pri tebe je nepriateľská technika alebo stavba. Proti nim je najlepšia raketa.",
"Enemies are bunched up — throw a grenade.":"Nepriatelia sa zhlukli — hoď granát.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Veľa nepriateľov — zapni reflex: čas sa spomalí a stihneš ich zložiť.",
"Aim at the enemy cluster and call in a strike.":"Zamier na zhluk nepriateľov a vyvolaj úder.",
"Targets are far — the railgun is stronger at long range.":"Ciele sú ďaleko — railgun je silnejší na veľkú vzdialenosť.",
"You have a temporary heavy MG — use it before it is recalled.":"Máš dočasný ťažký guľomet — používaj ho, kým ti ho neodvolajú.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkour: C pri behu — šmyk, skok pri rímse — vyliezť, skok pri stene vo vzduchu — odraz.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Guľky bijú najsilnejšie na 20–50 m. Zblízka a zďaleka sú citeľne slabšie — aj na teba.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Robot je ťažko poškodený. Odíď spod paľby — mimo boja sa pancier opraví sám.",
"One of our tanks is close. Walk up and press E to take control.":"Pri tebe je náš tank. Podíď a stlač E — budeš ho ovládať.",
"Man the turret — press E next to it.":"Obsaď vežu — E pri nej.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Je tu ticho. Prepni sa na družstvo alebo techniku bližšie k boju.",
"Reload early while no enemies are around.":"Prebíjaj sa vopred, kým nie sú nablízku nepriatelia.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Bež priamo po zelených šípkach stratéga — na jeho trase bežíš rýchlejšie.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Tlačidlo „◩ Stratégia\" — pohľad zhora: stav základňu, objednávaj vojsko, veľ družstvám.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Režim stratégie: stav základňu, objednávaj vojsko, vyvolávaj údery a veľ družstvám. Rovnaký kláves tam znamená ovládnuť vybraného.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Chceš velit sám? Vypni AI stratéga — rozkazy potom dávaš ty.",
"Third-person view — to see your robot.":"Pohľad z tretej osoby — aby si videl svojho robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tank: {0} — salva do bodu zamerania, {1} — dymová clona, {2} — preťaženie. {3} — späť k pechote.",
"Plenty of targets — fire a barrage.":"Cieľov je veľa — vypáľ salvu.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — vyššie/nižšie, ľavé tlačidlo — paľba, {2} — baranidlo do bodu zamerania.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Vyber družstvo — ľavým tlačidlom, rámikom alebo kartou vľavo. Pravé tlačidlo na zem — útočný pohyb ⚔, na nepriateľa — útok, na bod — ovládnutie.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Družstvá majú schopnosti: granáty, skok na jetpackoch, potlačenie, oprava. Tanky: salva, dym, preťaženie.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Rudy je veľa — vyber Veliteľstvo alebo továreň a objednaj vojsko v paneli vpravo.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Hromadia sa body velenia (BV) — záložka „Údery\": prieskum, delostrelecký úder, kapsula s družstvom, Orbitálny úder.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Budovy stavajú iba inžinieri: vyber inžiniera (tlačidlo v záložke „Stavba\" alebo kláves budovy), potom klikni na miesto. Extraktor (C) na žiariacej žile — viac rudy.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klikni na „RUDA\" vľavo hore — odkiaľ sa ruda berie a ako zrýchliť príjem.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — uložiť skupinu, 1…9 — vybrať ju, dvojité stlačenie — kamera k nej.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Vyber jednotku a ťukni na zelené „▶ Ovládnuť\" dole (alebo dvojité ťuknutie) — bojuješ sám. „◩ Stratégia\" ťa vráti späť.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Vyber jednotku a stlač zelené „▶ Ovládnuť\" dole alebo {0} (alebo dvojklik) — bojuješ sám. V boji ťa {1} vráti do stratégie.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Sivé tlačidlá sa dajú stlačiť tiež: ukážeme, čo chýba, ako dlho čakať a ako to napraviť.",
"RMB on the ground — rally point for this building's new troops.":"Pravé tlačidlo na zem — zhromaždisko pre nové vojsko tejto budovy.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Pravé tlačidlo — útočný pohyb ⚔: keď stretnú nepriateľa, zastavia sa a bojujú, potom idú ďalej. Dvojité pravé tlačidlo — pochod »: behom, bez zastavenia, strieľajú za pohybu. Držať/Ustúpiť — „Ďalšie rozkazy ▾\".",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: ťahaj prstom, dvoma prstami — priblíženie a otáčanie, minimapu môžeš ťahať prstom.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD a okraje obrazovky, Q/E — otáčanie, koliesko — výška (ku kurzoru), stredné tlačidlo — rotácia, minimapa — klik alebo ťahanie, Medzerník — k poslednému poplachu.",
