"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Stavia iba inžinier. Ak nie je vybraný, tlačidlo vyberie najbližšieho voľného a zapne plán; potom ľavé tlačidlo na miesto.",
