"All strategy keys":"Všetky klávesy stratégie",
"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"Zapnutý — sám stavia základňu, objednáva vojská a rozdáva rozkazy (tvoje rozkazy majú prednosť). Vypnutý — všetko robíš ty.",
"Auto-build on: the strategist builds the base with builders":"Automatická stavba zapnutá: stratég stavia základňu inžiniermi",
