"Attack-move":"Útočný presun",
"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Potom klikni (ťukni) na zem: idú a cestou strieľajú. Na nepriateľa — zaútočiť naň. To isté je pravé tlačidlo.",
"Run":"Behom",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Potom klikni (ťukni) na zem: bežia bez zapájania sa do boja. To isté je dvojité pravé tlačidlo.",
"2×RMB":"2× pravé tlačidlo",
"Selected groups stay put and return fire.":"Vybraní stoja na mieste a opätujú paľbu.",
"Retreat":"Ústup",
"Run back to the HQ (or nearest outpost) without engaging.":"Behom späť k Veliteľstvu (alebo najbližšiemu predsunutému postu) bez zapájania sa do boja.",
"Squads jet up through the dome portal and land at the enemy.":"Čaty vzlietnu na jetpackoch, prejdú portálom kupoly a pristanú pri nepriateľovi.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Ovládaj vybraného vojaka, tank alebo vežu sám z prvej osoby. Tá istá klávesa v boji ťa vráti do stratégie.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 vojaci: útočník, ťažký strelec, raketomet, zdravotník.",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"Autonómne bojové vozidlo: kanón a guľomet, salva, dym, forsáž.",
"Fast flying gunner, good against infantry.":"Rýchly lietajúci strelec, účinný proti pechote.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Elitné družstvo so silnými jetpackmi — môže sa zhodiť cez kupolu.",
"A lone railgun sniper.":"Osamelý ostreľovač s railgunom.",
"Fast scout: sees far and spots enemies.":"Rýchly prieskumník: vidí ďaleko a zvýrazňuje nepriateľov.",
"A squad drops from orbit right at the front line.":"Družstvo pristane z orbity priamo pri línii frontu.",
"Jetpacks II: infantry reaches the dome and can sky-assault.":"Jetpacky II: pechota dolietne ku kupole a môže sa zhodiť.",
