"New in v6.3":"Novinky vo v6.3",
"New in v6.2":"Novinky vo v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nový vzhľad rudy: rudné žily sú žiariace smaragdové brúsené kryštály na čiernom čadiči s iskrami a zelenou hmlou; extraktor je šesťhranný podstavec so včelím plástom na kupole a mrežovou vežou so zeleným majákom (pruh a zástavka — farba tímu)",
"New in v6.1":"Novinky vo v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Preferovaná trieda ako v Battlefielde (U, čísla po smrti): po smrti sa obnovíš v nej, ak je dostupná",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Technika z prvej osoby (V — zvonku/z kabíny); jemné automatické mierenie — v Nastaveniach",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Z Jadra sa dá ľahko dostať: Medzerník — k šachte, B — kapsula na povrch; efekty schopností sa po smrti resetujú",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Nekonečný postup: generáli a Maršal ★, úrovne kariéry, majstrovstvo zbraní a nadstavby, medaily, denné zákazky — obrazovka „Kariéra“",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Stratégia: plynulý zoom kolieskom, ikony a popisky nad jednotkami (Alt — všetky), panel „Vojská / Budovy“ vľavo",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Pravé tlačidlo — útok počas presunu, dvojklik pravým — pochod so streľbou za pohybu; zriedkavé rozkazy — v „Ďalšie rozkazy ▾“; tlačidlá sa neopakujú",
"New in v6":"Novinky vo v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Zbrane ako v strieľačkách: okamžité guľky, puška 720 rán/min, guľomet, spätný ráz, mierenie pravým tlačidlom, zásobníky a nabíjanie R, značky zásahov",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Ťažšia gravitácia, citlivejší jetpack, úskok na Z alebo 2× jetpack vo vzduchu; pri prepnutí do inej jednotky už zbraň nelieta s tebou",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inžinieri: vyber inžiniera, zvoľ budovu, polož plán; extraktory na rudných žilách; klikni na „RUDA“ — odkiaľ je príjem a ako ho zvýšiť",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Sivé tlačidlá sa dajú stlačiť — ukážeme dôvod a riešenie; väčšie tlačidlá, pás „Prebieha“, „▶ Ovládnuť“, Tab — jediná klávesa režimov",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera stratégie bez trhnutí a prevrátení, zoom ku kurzoru, minimapu možno ťahať",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nová technika: nájazdník „Jackal“, raketomet „Grad“ (samonavádzacie rakety), mínomet „Hammer“; Roj má „Wasp“, „Hive“, „Trebuchet“",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Stratég nemení rozkazy a nespamuje hlasom; boje prichádzajú k tebe; B — presun, Shift+B — do víru boja; kompas, H — ktorý cieľ",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Voľná hra (K) a samostatný postup (J), F2 — predvoľby; Esc — pauza a späť; ukladanie: sloty, export a import súboru",
"New in v5.3":"Novinky vo v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Let: silnejšia gravitácia ďaleko od meteoru, C vo vzduchu brzdí, ťah riadi ostrejšie; v portáli už nezostaneš visieť",
"New in v5":"Novinky vo v5",
"Endless war by default and battle scale: normal, large, epic":"Predvolene nekonečný boj a mierka bojov: bežná, veľká, epická",
"Save and load the battle (autosave every 3 minutes)":"Ukladanie a načítanie boja (automatické ukladanie každé 3 minúty)",
"Squadmates with callsigns: portraits, health and live chatter":"Družstvo s volacími znakmi: portréty, zdravie a živé rozhovory",
"Fog of war in strategy, friends and foes outlined differently":"Hmla vojny v stratégii, spojenci a nepriatelia zvýraznení inak",
"Camera fly-over when switching, portal aurora instead of rings":"Prelet kamery pri prepínaní, žiara portálu namiesto kruhov",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Vedľajšie úlohy, skratka cez nebo, moduly prvej expedície so zásobami, kryštály, ľad v kráteroch, prachové búrky",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Výcvik, kino režim s nahrávaním videí, sprievodná technika od stratéga",
