"Saves live only in this browser on this device (localStorage). Anyone else who downloads the game gets none of your saves. To move a battle to another computer or browser: \"Export to file\" here → \"Import from file\" there. Autosave runs every 3 minutes of battle and when you quit to the menu.":"Uložené hry sa ukladajú len v tomto prehliadači na tomto zariadení (localStorage). Ak si hru stiahne niekto iný, tvoje uložené hry mať nebude. Prenos boja na iný počítač alebo prehliadač: tu „Exportovať do súboru“ → tam „Importovať zo súboru“. Automatické ukladanie prebieha každé 3 minúty boja a pri odchode do menu.",
