"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Granát: drž G — uvidíš oblúk a kruh výbuchu; veď prstom po tlačidle — uhol; pusti — hod.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Granát: drž {0} pre oblúk a kruh výbuchu, pusti pre hod. Dosah — uhlom pohľadu, koliesko — sila, pravé tlačidlo — pod nohy.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Granáty: drž G — oblúk letu, bod a kruh výbuchu, vzdialenosť; pusti — hod. Dosah uhlom pohľadu, koliesko — sila, pravé tlačidlo — pod nohy",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Granát sa odráža a kotúľa po svahu, výbuch o 2,5 s; 2 granáty, obnova 9 s; ikona-varovanie pri nepriateľskom granáte nablízku",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Granát: drž — oblúk a bod výbuchu, pusti — hod · forsáž tanku",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — drž: vidno oblúk a kruh výbuchu, pusti — hod. Výbuch o 2,5 s, 2 granáty.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granát ({0}): drž — oblúk letu, bod a kruh výbuchu, vzdialenosť; pusti — hod; krátke stlačenie hodí hneď. Dosah uhlom pohľadu, koliesko — sila, pravé tlačidlo — hod zospodu. Telefón: drž G a veď prstom.",
