"GESTURES":"GESTÁ",
"The Polygon works in developer mode only":"Cvičisko funguje len v režime vývojára",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Cvičisko: nekonečný boj v strede mapy s posilami. X — ovládnuť tam vojaka",
