"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Ťukni na „Zameranie“ — priblíženie. Ďalšie ťuknutie — späť.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Družstvo ťa nasleduje. Otvor ☰ → „Pauza“ → dlaždicu „Družstvo so mnou“ — zmení sa na „Konám sám“.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inžinier je vybraný — ťukni na „◆ Ťažiť kryštály“ v jeho karte dole (alebo ťukni na zelené kryštály).",
"Training complete!":"Výcvik dokončený!",
"steps":"krokov",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Vieš stavať základňu, objednávať vojsko, veliť a skákať do boja. Ďalej — skutočný zápas: Sprievodca ti poradí priebežne.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Vieš sa pohybovať, lietať, strieľať, skrývať sa a veliť družstvu. Ďalej — skutočný zápas.",
"Real battle":"Skutočný boj",
"Again":"Ešte raz",
"done":"dokončené",
"you are on PC: keyboard and mouse":"máš PC: klávesnica a myš",
"you are on a phone: touch screen":"máš telefón: dotyková obrazovka",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Bezpečné pieskovisko: nepriatelia sú nehybné figuríny, nikto na teba nestrieľa. Krok sa započíta, až keď akciu naozaj urobíš sám.",
"Show others (training for the other device)":"Zobraziť ďalšie (výcviky pre iné zariadenie)",
"Old training (v7.1)":"Starý výcvik (v7.1)",
"Back to the normal device mode":"Vrátiť bežný režim zariadenia",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Výcvik pre iné zariadenie znova načíta stránku v jeho režime (PC — myš a klávesnica, telefón — dotyky; na PC si dotyky pohodlne vyskúšaš v Chrome: F12 → ikona telefónu).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Výcvik ×4: samostatné krok za krokom výcviky „Stratégia“ a „Strelec“ pre PC a pre telefón. Bezpečné pieskovisko s figurínami, zvýraznené správne tlačidlo, šípky, animované klávesy, myš a gestá; krok sa počíta len za skutočnú akciu, „zopakovať krok“, postup hore a odmena na konci",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Ponuka Výcvik sama zobrazí výcviky pre tvoje zariadenie; „Zobraziť ďalšie“ — všetky štyri na ľubovoľnom zariadení; „Starý výcvik (v7.1)“ ostal zachovaný",
"New in v7.2":"Novinky vo v7.2",
"NEW IN v7.2":"NOVINKY VO v7.2",
"No grenades left":"Granáty došli",
"Rocket and grenade recharging · {0} s":"Raketa a granát sa nabíjajú · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Vľavo — pohyb, vpravo — rozhľad · ťuknutie na nepriateľa — raketa / granát · 2 ťuknutia — reflex · 3 ťuknutia — delostrelecký úder",
"Less":"Menej",
"More":"Viac",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Nablízku je nepriateľská technika alebo stavba — ťukni na ňu: vyletí raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Veľa nepriateľov — rýchlo dvakrát ťukni na voľné miesto vpravo: reflex spomalí čas.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Zamier na zhluk nepriateľov a ťukni 3-krát — delostrelecký úder.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Ľavý palec — pohyb, pravý — rozhľad. Keď máš nepriateľa v mieridle, vojak páli sám.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ vľavo pri okraji — jetpack: ťuknutím skočíš, podržaním letíš.",
"Old v7.2 layout":"Staré rozloženie v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Veď prst po pravej polovici obrazovky — pod prstom sa objaví páčka rozhľadu.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dotkni sa ľavej strany a veď prst — pod prstom sa objaví páčka. Dôjdi k zelenej značke.",
"Hold the \"Jet\" button at the left edge.":"Podrž tlačidlo „Jetpack“ pri ľavom okraji.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Pravou páčkou zamier na figurínu — vojak páli sám, keď je mieridlo na cieli.",
"Tap the dummy on the screen — a rocket flies.":"Ťukni na figurínu na obrazovke — vyletí raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Ťukni na figurínu — vyletí granát (oblúkom, presne do cieľa).",
"Double tap an empty spot on the right quickly.":"Rýchlo dvakrát ťukni na voľné miesto vpravo.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Ľahký režim pre slabé telefóny: nižšie rozlíšenie, bez tieňov a skreslenia, polovica botov a častíc, najviac 30 FPS; ak FPS < 25, rozlíšenie zníži sám. Na telefóne je predvolene zapnutý (Nastavenia → Grafika → „Ľahký režim“; alebo ?lite=1 / ?lite=0 v odkaze).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefón: nové ovládanie. Vľavo — pohyb, vpravo — rozhľad (obe páčky sa objavia pod prstom). Len ľavý palec — „auto“; keď použiješ pravý, vojak páli sám, len kým je mieridlo na nepriateľovi. Ťuknutie na nepriateľa — raketa alebo granát, 2 ťuknutia — reflex, 3 ťuknutia — delostrelecký úder. Automatické prebíjanie. Jetpack — tlačidlo pri ľavom okraji. Dolné rohy sú voľné, minimapa v rohu, nápovedy zavrieš krížikom, úlohu môžeš zbaliť. Staré rozloženie: Nastavenia → Telefón.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Nápovedy (vyskakovacie aj Sprievodca) — jeden vypínač v nastaveniach. Za koho hráš (typ vojaka alebo techniky) — štítok „Ty: …“ v HUD. Optiky pušky a guľometu sú priehľadné. Panel „Arzenál“ je ukotvený vpravo, dá sa zbaliť aj vypnúť. Režim „sólo bez družstva“ (J) je odstránený. Hlas AI stratéga sa už neopakuje dookola. Tanky majú ukazovateľ veže voči korbe. Kurzor už na začiatku výcviku stratégie nezmizne.",
