"Voice of hints and curator":"Hlas nápovedí a Kurátora",
"Advanced: custom class order":"Pokročilé: vlastné poradie tried",
"Voice of hints & curator":"Hlas nápovedí a Kurátora",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefón: tri režimy páčok. Len ľavá — „auto“ (silný magnet, slabšie strely). Len pravá — mieridlo sa zapne samo, silnejší magnet, presnejšia streľba. Obe naraz — bez mieridla, slabší magnet a presnosť. Tlačidlo 👁 vpravo skryje/vráti rozhranie.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefón: stratégia je zjednodušená — len inžinier a budovy. Vľavo karty (inžinier, Veliteľstvo, Kasárne…): ťuknutím tam preletí kamera, dolná lišta ukáže, čo postaviť/vyrábať. „Do boja“ — vľavo hore. Armáda bojuje sama. Plná stratégia — Nastavenia → Telefón.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Ovládnutie — dva prepínače: „Družstvá“ a „Technika“ (technika je na telefóne predvolene vypnutá — riadi ju AI). Keď je technika vypnutá, E (na telefóne tlačidlo vpravo) pri vlastnom stroji — sadnúť k jeho zbrani: stroj ide sám, ty strieľaš. Staré vlastné poradie tried je v „Pokročilých“. Jednotka ti odpovie cez vysielačku, keď ju ovládneš.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Múdre nápovedy: základné nápovedy sa po 2. spustení vypnú samy, no hra ti pripomenie funkciu, ktorú nepoužívaš. Prepínače: základné / pokročilé / vzácne, zvlášť hlas nápovedí a Kurátora.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflex sa nabíja zo zabití (série nabijú viac). Spolubojovníci zaostali alebo padli — stratég ti zhodí nových (drahšie než bežné posily). Grafika a zvuk v7.2gfx sú zlúčené: výbuchy v mrakoch, dym, trosky, akustika šácht a kráterov. Dátum zostavenia je teraz skutočný.",
