"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Kariéra a uloženia ostávajú nedotknuté. V boji je to isté menu tlačidlo „🛠 Menu“ vpravo hore{0}.",
"New developer match":"Nový zápas vývojára",
"all unlocked, endless ore, instant build, arsenal":"všetko odomknuté, nekonečná ruda, okamžitá stavba, arzenál",
"Trainings — all 4":"Výcviky — všetky 4",
"PC and phone (strategy and shooter)":"PC a telefón (stratégia a strelec)",
"Cinema: split screen":"Kino: rozdelená obrazovka",
"strategist bot left, shooter bot right":"vľavo bot-stratég, vpravo bot-strelec",
"Cinema: everything built":"Kino: všetko postavené",
"both bases built and upgraded — for footage":"obe základne sú postavené a vylepšené — na natáčanie",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino režim — rozdelená obrazovka: vľavo bot-stratég (pohľad zhora na základňu a armádu), vpravo bot-strelec z prvej osoby. Tlačidlá dole (a klávesy S, P): „Rozdelená obrazovka“ a „★ Všetko postavené“ — obe základne postavené a vylepšené na natáčanie.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Jadro a tunely cez meteor sú preč — meteor je plný, boj prebieha len na povrchu.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefón: 👁 skryje HUD, ale ponechá jetpack, ⇆, páky a značku úlohy. „◎ Mieridlo“ (len pravý prst) — výrazne silnejší a širší magnet; sila magnetu pre všetky tri režimy — Nastavenia → Ovládanie → „Pokročilé“. Pri dele vozidla sa tlačidlo volá „Zosadnúť“.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Výcvik: na telefóne len telefónne lekcie, na PC len PC. Všetky 4 sú v menu „🛠 Vývojár“. Režim vývojára a Arzenál sú teraz jedno menu (v boji — „🛠 Menu“ vpravo hore, na PC aj F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Štýly grafiky „Dendy (8-bit)“ a „16-bit“: Nastavenia → Grafika → „Štýl grafiky“ (podrobnosti — tlačidlo ⚙). Ak je FPS v prvých ~10 s zápasu pod 24, Dendy sa zapne samo (pod 20 — väčší pixel, 120 riadkov); oznam „späť na normál“ vráti bežnú grafiku natrvalo. Tvoja vlastná voľba v menu má vždy prednosť.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D modely prostredia (ruiny, vraky, opevnenia) — len tie s dobrým hodnotením, načítavajú sa podľa potreby. Vypnúť: Nastavenia → Grafika → „Nové 3D modely prostredia“.",
