"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Stavba vojakmi: E (na telefóne „Vstúpiť“) pri vlastnej stavbe — vojak stavia sám, spolubojovníci nablízku pomáhajú. Ak sú inžinieri zaneprázdnení, stratég sám požiada o pomoc — značka „STAVBA“.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Značky stratéga: stratég dá ⌖ na skupinu nepriateľov pri tebe — o 8 s tam udrie delostrelectvo a blízke vlastné raketomety „Grad“ vystrelia salvu. Aj tvoj delostrelecký úder zo stratégie dostane podporu „Gradov“.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrýše so zbraňami v nákladných kontajneroch a zrútených satelitoch (📦 vidno zo 70 m): E — guľomet na 90 s, zápalná munícia alebo rakety, plus plné granáty. Plazenie: Ctrl — ľahnúť si / vstať (nižšie, tichšie, presnejšie, ale pomaly).",
