"Link copied":"Odkaz skopírovaný",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Hrať teraz“ — prvé tlačidlo menu: krátky prelet pod nebom-portálom — a rovno do boja (preskočiť — ľubovoľná klávesa alebo ťuknutie).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Zásahy sú cítiť: kovový zvuk a iskry, značka zničenia pri zameriavači (headshot — žltá), séria ×N, plynulé trasenie od výbuchov, spomalenie pri dôležitých zásahoch. Trasenie, spomalenie a nápovedu možno vypnúť v Nastaveniach.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Výsledky zápasu: čas, zničené ciele, najlepšia séria, ★ MVP a najlepšie družstvo, karta zápasu — „⇪ Zdieľať“, PNG alebo odkaz na hru.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Nápoveda „čo robiť teraz“ vľavo pod zdrojmi: rozkaz stratéga, bod na ovládnutie, útok Roja. ✕ alebo F7 — zbaliť.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Boj sa uloží sám, keď zatvoríš alebo skryješ kartu — v menu „⟲ Pokračovať“.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Verzia v7.5 zostala v menu „🕘 Verzia hry“ — ak sa nová nebude páčiť. Odteraz sa odosielajú anonymné štatistiky (bez mien a e-mailov); vypnúť sa dajú v Nastaveniach.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Hrať teraz“, odozva zásahov, výsledky zápasu s kartou, nápoveda „čo robiť“, automatické ukladanie",
"and older: v7.5, v7.4, milestones v1–v7.0":"a staršie: v7.5, v7.4, medzníky v1–v7.0",
"New in v7.6":"Novinky vo v7.6",
"NEW IN v7.6":"NOVINKY VO v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Výber frakcie pred zápasom: „Konzorcium“ (ťažká pechota v silovom pancieri, pancier a delostrelectvo) alebo „Roj“ (rýchlosť, kŕdle dronov, ťažké výstrely so skreslením). AI hrá za druhú. Voľba sa zapamätá.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Každá frakcia má vlastnú techniku a unikáty: Konzorcium — tank „Nosorožec“ a „Keramitové dosky“, Roj — „Kŕdeľ dronov“ a „Fázové jetpacky“. Rovnováha overená zápasmi botov.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Krátery po výbuchoch: delostrelectvo, rakety a tankové kanóny hĺbia v meteore jamy — dajú sa nimi prechádzať aj prejsť vozidlom a v nich sa dá ukryť.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pohľad z tretej osoby pre vojaka (V, zapamätá sa; na telefóne — Ovládanie) a plynulá kamera vozidla so značkou, kam dopadne náboj z kanóna.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Verzia v7.6 zostala v ponuke „🕘 Verzia hry“ — keby sa ti nová nepáčila.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcie Konzorcium / Roj s výberom pred zápasom, krátery po výbuchoch, pohľad z tretej osoby",
"and older: v7.6, v7.5, milestones v1–v7.0":"a staršie: v7.6, v7.5, míľniky v1–v7.0",
