"Anomaly ahead":"Anomália vpredu",
"dormant":"spí",
"Anomaly ahead! The vein is singing — go around!":"Anomália vpredu! Žila spieva — obchádzame!",
"Hear that hum? A singing vein. Keep clear!":"Počuješ ten hukot? Spievajúca žila. Nepribližuj sa!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomália! Vzduch sa krúti — to je vír, obíď ho!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kamene visia vo vzduchu… Vír! Nelez tam!",
"Anomaly ahead — it is crackling with current!":"Anomália vpredu — praská od prúdu!",
"Rods and lightning — a Crackler. It loves armour!":"Tŕne a blesky — Praskáč. Pancier miluje!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomália! Zem sa chveje od horúčavy — Žeravisko!",
"Careful, a Brazier underfoot!":"Opatrne, pod nohami je Žeravisko!",
"Anomaly — green mist! Acid, hold your breath!":"Anomália — zelená hmla! Kyselina, nedýchajte!",
"The mist is drifting our way, go around!":"Hmla sa plazí k nám, obchádzame!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomália! Vzduch ako sklo — Šošovka, ohýba guľky!",
"Everything is warping… a Lens nearby!":"Obraz sa deformuje… Šošovka je blízko!",
"Ha! An enemy walked right into the anomaly!":"Ha! Nepriateľ vliezol rovno do anomálie!",
"Got him! Lure them into anomalies!":"Mám ho! Zalákaj ich do anomálií!",
"Beautiful zap! One less tin can.":"Krásny výboj! Jedna plechovka menej.",
"The anomaly got me!":"Zasiahla ma anomália!",
"Ow! Don't go in there!":"Au! Nechoďte tam!",
"Discharged! It is dormant now.":"Vybitá! Teraz spí.",
"Clear, the anomaly is discharged.":"Čisté, anomália je vybitá.",
"They say veins hide artifacts. Only first the vein sings…":"Vraj sa v žilách skrývajú artefakty. Len že žila najprv spieva…",
"Throw a bolt first, then walk. Old habit.":"Najprv hoď skrutku, potom choď. Stará poverka.",
