" — close":" — zavrieť",
"Supply drop":"Zásobovací box",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Zhodí box vedľa tvojich síl: náboje, granáty, rakety, diely zbraní, opravárenská súprava.",
"\"Grad\" rocket strike":"Úder „Gradu“",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 rakiet na veľkú plochu o 3 sekundy — rýchlejšie a širšie než delostrelecký úder.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Podpora: box, prieskum, „Grad“, delostrelecký úder (potom 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"POZOR: „Grad“ Roja mieri na vašu oblasť!",
"Warning! Rocket salvo on our position!":"Pozor! Raketová salva na našu pozíciu!",
"take the supply crate":"vziať zásobovací box",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomálie na meteore (vlna 1): „Spievajúca žila“ — svietiaci zelený kryštál, ktorý hučí a rytmickými pulzmi zasahuje všetkých nablízku; „Vír“ priťahuje a mláti, „Praskáč“ šľahá bleskami medzi tŕňmi, „Žeravisko“ vzbĺkne pod nohami, „Kyslá hmla“ a „Šošovka“ (ohýba guľky aj obraz) sa unášajú okolo.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomálie vycítiš vopred (hukot, žiara, chvenie vzduchu). Vybi ich granátom, raketou alebo skrutkou (E pri anomálii): zaspí a občas zanechá artefakt s plusom aj mínusom. Družstvo ťa varuje cez vysielačku a nepriatelia (aj spojenci) do nich občas vlezú — zalákaj ich!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Podpora za veliteľské body: 4 v boji (📡 na telefóne) — zásobovací box, prieskum, úder „Gradu“, delostrelecký úder podľa zameriavača. Stratég vidí anomálie na mape až po prieskume.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Zásobovacie boxy v ruinách starých expedícií, pri veliteľstvách a vedľa dokončených budov: náboje, granáty, rakety, diely zbraní (odomykajú doplnky).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Verzia v7.7 zostala v ponuke „🕘 Verzia hry“. Anomálie sa dajú vypnúť v Nastaveniach.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomálie („Spievajúca žila“ a 5 ďalších), vybíjanie skrutkou a granátom, artefakty, podpora za veliteľské body, zásobovacie boxy",
"and older: v7.7, v7.6, milestones v1–v7.0":"a staršie: v7.7, v7.6, míľniky v1–v7.0",
"New in v7.8":"Novinky vo v7.8",
"NEW IN v7.8":"NOVINKY VO v7.8",
"Close":"Zavrieť",
"Anomalies on the meteor":"Anomálie na meteore",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ v rohu otvorí ponuku pauzy: Pokračovať, Začať odznova, Výcvik, Grafika, Nastavenia, Hlavná ponuka (s potvrdením). Telefón: ☰ vpravo hore (akcie v boji — dlaždica „⚡ Akcie“); PC: tlačidlo „☰ Ponuka“ vpravo hore alebo Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika je predvolene vždy normálna — Dendy len ak si ju vyberieš: prepínač „Grafika: Normálna / Dendy (8-bit) / 16-bit“ je priamo v hlavnej ponuke a v pauze. Ak hra silno seká, objaví sa tip s tlačidlom „Zapnúť Dendy“.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefón a tablet: akčné tlačidlo „✋“ vpravo sa objaví, len keď je nablízku niečo na robenie — „Vziať“ (úkryt, box), „Nastúpiť“ (vozidlo, veža, delo), „Stavať“, „Zosadnúť“, „Skrutka“ pri anomálii. Môžeš tiež len ťuknúť na zvýraznený predmet.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefón, stratégia: drž prst ~0,3 s (telefón zavibruje, objaví sa žltý krúžok) a ťahaj — výberový rámik; bežné potiahnutie posúva kameru. Vpravo je aj tlačidlo „Rámik“; vo výcviku krok „Rámik“ uzná aj výber družstva ťuknutím.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefón: drobné tlačidlá sa ľahšie trafia, zoznam podpory 📡 je väčší, panely stratégie už neprekrývajú pauzu a výsledky. Verzia v7.8 zostala v ponuke „🕘 Verzia hry“.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Ponuka ☰ na telefóne a PC, žiadne automatické Dendy, tlačidlo „✋“ na dotyku, výber rámikom na telefóne",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Seká to? Skús grafiku Dendy — je ľahšia.",
"Turn on Dendy":"Zapnúť Dendy",
"Use":"Akcia",
"Man gun":"K delu",
"Board":"Nastúpiť",
"Man it":"Nastúpiť",
