"Pause: resume, restart, training, graphics, settings, main menu":"Pauza: pokračovať, odznova, výcvik, grafika, nastavenia, hlavná ponuka",
"Menu: pause, restart, training, graphics, settings":"Ponuka: pauza, odznova, výcvik, grafika, nastavenia",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Drž prst na zemi ~0,3 s — telefón zavibruje a objaví sa žltý krúžok — a bez zdvihnutia ťahaj: vznikne rámik. Alebo tlačidlo „Rámik“ vpravo. Stačí aj ťuknúť na družstvo.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pre celú obrazovku na iPhone: „Zdieľať“ ⬆ → „Pridať na plochu“ — hra sa otvorí bez panelov Safari.",
"Open portal-meteor.pages.dev for that.":"Na to otvor stránku portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Ťuknutie — vybrať · ťuknutie na zem — ísť · drž — ponuka rozkazov · drž a ťahaj — rámik · 2 prsty — priblíženie",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Hrdinka-vrahyňa: výpady-teleporty, katana, shurikeny. Sama skáče po zónach nepriateľa a rozsekáva roboty. 1 na stranu.",
"Shadow protocol":"Protokol „Tieň“",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Výskum: odomkne robo-ninju v Kasárňach. Vyžaduje dokončenú továreň na mechy.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Hrdinka (1 na stranu): sama sa teleportuje po zónach nepriateľa a rozsekáva roboty; môžeš ju ovládnuť a hrať ručne.",
"is ready. She works on her own (AUTO) — possess her to play manually":"je pripravená. Pracuje sama (AUTO) — ovládni ju, aby si hrala ručne",
"Robo-ninja ready for action":"Robo-ninja je pripravená do boja",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Prieskum: nepriateľ má robo-ninju!",
"Warning! The enemy has a robo-ninja. Stay together":"Pozor! Nepriateľ má robo-ninju. Držte spolu",
"cyber blinks":"kyber-výpady",
"Too far for a dash — get closer or teleport":"Na výpad je to ďaleko — priblíž sa alebo použi teleport",
