"order":"rozkaz",
"nearby":"nablízku",
"Zone cleared":"Zóna vyčistená",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ SÚBOJ NINJ! Blok tesne pred zásahom odrazí úder, výpad je úhyb. Sleduj záblesk pred úderom",
"The two ninjas have met in a duel!":"Dve ninje sa stretli v súboji!",
"⚔ Duel won! Our ninja prevails":"⚔ Súboj vyhraný! Naša ninja je silnejšia",
"⚔ Duel lost…":"⚔ Súboj prehraný…",
"ninja duel":"súboj ninj",
"POSTURE BROKEN":"POSTOJ NARUŠENÝ",
"Teleport":"Teleport",
"Teleport: aim at the ground (up to 150 m)":"Teleport: zamier na zem (do 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sama skáče po zónach nepriateľa a seká. Joystick / WASD — pauza 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ručne: ťuknutie na nepriateľa — výpad a úder, potiahnutie — seknutie, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ručné ovládanie: ľavé tlačidlo — katana, pravé tlačidlo — blok, Shift — výpad, Q — shurikeny, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: ťuknutie na nepriateľa — výpad a rez, potiahnutie vpravo — sek, ● — úder, 🛡 — blok (načas = parírovanie), ⇑ — blink, ✦ — shurikeny, ◎ — teleport, AUTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: ľavé tlačidlo — katana (podržať — ťažký rez), pravé tlačidlo — blok (načas = parírovanie), Shift/Z — skok, Q — shurikeny, G — teleport na zameriavač, skok vo vzduchu — dvojitý skok / beh po stene, {0} — AUTO",
