"Research complete: Shadow protocol — the robo-ninja is available in the Barracks":"Výskum dokončený: Protokol Tieň — v Kasárňach je dostupná robo-ninja",
"Shadow protocol ready. The robo-ninja can be deployed":"Protokol Tieň je pripravený. Môžeš privolať robo-ninju",
"✶ Our robo-ninja is down. Deploy her again in the Barracks":"✶ Naša robo-ninja je zničená. Privolaj ju znova v Kasárňach",
