"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Rádio Portal Meteor: 100+ skladieb od EDMITRY priamo v hre — tlačidlo 📻 (PC: kláves 5, [ ] — skladba). Hudba sa streamuje na požiadanie a hru nezaťažuje; hlasitosť a automatické spustenie nájdeš v Nastaveniach, plus odkaz „Počúvať na Spotify“.",
