"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 vpravo — Rádio Portal Meteor: hudba od EDMITRY počas boja.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Rádio Portal Meteor: hudba od EDMITRY počas boja. [ ] — skladba.",
"Radio Portal Meteor (EDMITRY): volume":"Rádio Portal Meteor (EDMITRY): hlasitosť",
"Radio: start by itself in battle":"Rádio: spustiť samo v boji",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: kyborg s katanou. Odomkne sa v Kasárňach výskumom „Protokol Tieň“ (potrebná továreň na mechy). Sama sa teleportuje do zón nepriateľa, rozsekáva nepriateľov (bez krvi — iskry), robí výpady, hádže shurikeny, vedie súboje s nepriateľskou ninjou. Ovládni ju — režim AUTO alebo ručné ovládanie (na telefóne má vlastné tlačidlá).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Rádio Portal Meteor: 103 skladieb od EDMITRY priamo v hre. Kláves 5 (dá sa zmeniť), na telefóne — ☰ → Nastavenia → Zvuk. Hlasitosť a „spustiť samo v boji“ nájdeš v nastaveniach; hudba sa stíši pri výbuchoch a pod hlasom vysielačky.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Nové jazyky: uzbečtina a tadžičtina — kompletne; čínština, španielčina, portugalčina — čiastočne. Nový výber jazyka v menu vedľa „Nový zápas“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefón: „skryť ikony“ 👁 zoskupí zvyšné tlačidlá do upraveného stĺpca pri pravom okraji; na výšku sa už nič neprekrýva; iPhone — hra už nebojuje s gestami Safari a „Zdieľať → Pridať na plochu“ ju spustí na celú obrazovku.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Z v7.8.1: menu ☰ v rohu (pauza, odznova, výcvik, grafika), bez automatického Dendy, tlačidlo akcie ✋ na telefóne. v7.8.1 a v7.8 zostali v menu „🕘 Verzia hry“.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Robo-ninja, rádio EDMITRY, uzbečtina a tadžičtina, pohodlie na telefóne a iPhone",
