"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Bombardér zhodí 10 bômb na 80 m páse, ktorý prilieta od tvojej základne (v boji — v smere tvojho pohľadu). Po 3,5 s zanechá krátery.",
"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Ohnivá zóna 12 m horí 9 sekúnd: poškodenie v čase, potlačenie, dym. Po 2,5 s. Zapáli metán.",
