"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Roj. Od 12:00 zápasu. Tu rastie kráčajúci stroj „Kosec“ (jeden na armádu).",
"Super-heavy tank \"Bastion\"":"Superťažký tank „Bastión“",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konzorcium. Boss: 15000 trup, kanón, 2 guľomety, rakety. Veľmi pomalý. Slabé miesto — zadná časť. Jeden na armádu.",
"Walker \"Reaper\"":"Kráčajúci stroj „Kosec“",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Roj. Boss: 12500 trup, lúč skreslenia, dupot. Prekračuje bariéry. Slabé miesto — jadro pod bruchom. Jeden na armádu.",
