"Light and medium vehicles go into the nearest open tunnel":"Ľahká a stredná technika ide do najbližšej otvorenej tunelovej nory",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Roj. Družstvá do 70 m od nory (a vybrané), ako aj vybraná ľahká/stredná technika (Šakal, Kladivo, Grad) prejdú tunelom a vyjdú na druhom konci. Alebo: vyber a pravé tlačidlo/ťuknutie na noru.",
