"{0} while running — slide · jump at a wall — wall-jump":"{0} za behu — šmyk · skok pri stene — odraz od steny",
"Bullets hit hardest at 20–50 m":"Strely zasiahnu najsilnejšie na 20–50 m",
"Badly damaged — get out of the fire, armor self-repairs":"Si ťažko poškodený — vyjdi spod paľby, pancier sa opraví sám",
