"SABOTAGE":"SABOTÁŽ",
"Living world: requests, hero quests, breakthrough ops":"Živý svet: prosby vlastných, úlohy hrdinov, predel boja",
"Living world":"Živý svet",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Vlastní prosia o pomoc a odmeňujú, hrdinovia dávajú úlohy, zaseknutý front sa láme operáciou",
"A request":"Prosba vlastných",
"Breakthrough":"Predel boja",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Vlastní občas prosia o pomoc: hlas v rádiu, karta „PROSBA“ a značka ✋. Družstvo je pod paľbou — znič nepriateľov v jeho blízkosti. Odmena: vojak v kapsule zo základne, zbraň z kufra buginy, miesto strelca alebo krytie z orbity. Nechceš — ✕ alebo to ignoruj.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veterán-prieskumník „Sova“ ponúka úlohu. Y — prijať (N — odmietnuť). Choď k značke ★, zlikviduj stráže a postoj pri pilotovi 3 s — pridá sa do tvojho družstva.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Front sa zasekol — veliteľstvo ponúka predel. Y — prijať. Drž retranslátor 8 s bez nepriateľov nablízku: nepriateľská mapa je viditeľná 60 s. Generátor — nepriateľské veže mlčia 2 min. V režime Stratég — „Prideliť družstvu“. Nepriateľ to vie tiež: sleduj ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Naši prosia o pomoc: karta „PROSBA“ a značka ✋. Znič nepriateľov pri družstve pod paľbou — dostaneš odmenu. ✕ — preskočiť.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Hrdina „Sova“ ponúka úlohu — ťukni na „Prijať“. Choď k ★, zlikviduj stráže, postoj pri pilotovi.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Front sa zasekol — ťukni na „Prijať“ a drž retranslátor 8 s: nepriateľská mapa sa na minútu odkryje.",
"Pod redeploy from the base: {0} m — through the sky portal":"Presun kapsulou zo základne: {0} m — cez nebeský portál",
"Pod away from the base! Hold on — exit over the target.":"Kapsula vyštartovala zo základne! Držte sa — výstup nad cieľom.",
"Landed at the objective!":"Výsadok pri cieli!",
"LAUNCH FROM BASE":"ŠTART ZO ZÁKLADNE",
"LANDING":"PRISTÁTIE",
"REDEPLOY":"PRESUN",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Oceľový chmýr sa prilepil — leptá pancier −2/s. Postoj 3 s mimo boja alebo choď k inžinierovi",
"An engineer brushed the fluff off":"Inžinier zmietol chmýr",
"The fluff fell off — armour is safe":"Chmýr opadal — pancier je celý",
"The firefly swarm scattered by the blast":"Roj svetlušiek rozohnaný výbuchom",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"OCEĽOVÝ CHMÝR −2/s · stoj 3 s alebo hľadaj inžiniera",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Konvoj „Ľaváka“ je pripravený: dva „Šakaly“. Drž sa nablízku — bez teba čakajú",
"The convoy is waiting for you":"Konvoj na teba čaká",
"Ambush! Cover the Jackals!":"Zálusk! Kry „Šakalov\"!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"Konvoj došiel ({0} z 2)! +2 BV, +150 rudy, „Šakali\" sú tvoji",
"The parts are delivered! Thanks, commander.":"Diely sú na mieste! Vďaka, veliteľ.",
"Show tips again":"Zobraziť tipy znova",
"Reset":"Obnoviť",
