"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Hlavný bojový tank: kanón a guľomet. Konzorcium má „Buldoga\" (odolnejší), Roj „Pavúka\" (rýchlejší).",
"Heavy tank":"Ťažký tank",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Autonómny lietajúci strelec: rýchly, krehký, bojí sa protilietadlovej obrany.",
"Upgrade":"Vylepšenie",
"Longer, faster jetpacks for all infantry.":"Jetpacky s dlhším dosahom a rýchlejšie pre celú pechotu.",
"Extractors mine more ore.":"Extraktory ťažia viac rudy.",
"Army-wide levels: less damage taken / more damage dealt.":"Úrovne pre celú armádu: menej prijatého poškodenia / viac spôsobeného.",
"Levels":"Úrovne",
"Base":"Základňa",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Srdce základne: družstvá, inžinieri, kapsuly, výskum. Strata veliteľstva znamená prehru.",
"Produces: ":"Vyrába: ",
"Launch pad":"Štartovacia plošina",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silo pri Veliteľstve: odtiaľto štartujú kapsuly, zásobovacie bedne a bombardéry — cez nebeský portál k cieľu. Stavať na nej sa nedá.",
"Economy":"Ekonomika",
"Key building":"Kľúčová budova",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Slabé miesto — zadná časť (motor): poškodenie ×{0}. Kanón, 2 guľometné veže, raketový blok; otáča sa veľmi pomaly — obíďte ho zboku.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Slabé miesto — žiariace jadro pod bruchom: poškodenie zospodu ×{0}. Lúč skreslenia a plošný dupot; prekračuje bariéry — držte odstup, nestojte v zhluku.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Proti nemu: letecké bomby a delostrelectvo (×{0}), rakety (×{1}), kobercové bombardovanie; guľky ho sotva poškrabú (×{2}).",
"Faction":"Frakcia",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Rýchle stroje, kŕdle dronov, tunely a regenerácia. Pechota je ľahšia, ale rýchlejšia; kanóny a koľajnicové zbrane bijú silnejšie.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Ťažká pechota v silovom pancieri, betónové bariéry, opravy a delostrelectvo. Pomalšia, ale odolnejšia.",
