"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Pozeráš zhora a veliš celej armáde: staviaš základňu, posielaš družstvá. Armáda bojuje aj bez teba.",
"You lead one squad: the camera is above it, tap the ground to move.":"Vedieš jedno družstvo: kamera je nad ním, ťuknutím na zem určíš, kam ísť.",
"The mode button is at the top right: tap for the next mode.":"Tlačidlo režimu je vpravo hore: ťuknutím prepneš na ďalší režim.",
"Next":"Ďalej",
"Got it":"Jasné",
"buttons":"tlačidlá",
"clean":"čisto",
"Messages":"Správy",
"nothing yet":"zatiaľ prázdne",
"tap to close":"ťuknutie — zavrieť",
"Third-person view — tap 🎥 to go back":"Pohľad z tretej osoby — ťukni na 🎥 pre návrat",
"Third-person view — {0} to go back":"Pohľad z tretej osoby — {0} pre návrat",
"the gamepad view button or ":"tlačidlo pohľadu na gamepade alebo ",
